  async function replaceArtwork(file:File|undefined){if(!file||!layer)return;try{if(/\.psd$/i.test(file.name)){const report=await engine.current.psd(await file.arrayBuffer(),file.name);let count=0;commit('Replace PSD artwork',p=>{count=replacePsdArtwork(p,sceneId,report);});setIssues(report.issues);tell(`${count} PSD layers replaced; rigs and animation preserved.`);return;}if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Replace a layer with PNG, JPEG, or WebP artwork.');const image=await createImageBitmap(file),old=project.assets.find(a=>a.id===layer.assetId);if(!old||image.width!==old.width||image.height!==old.height){image.close();throw new Error('Replacement artwork must have the same dimensions to preserve this rig.');}image.close();const asset={...old,id:id(),name:file.name,mime:file.type,data:await fileData(file)};commit('Replace artwork',p=>{p.assets.push(asset);const target=p.scenes.find(s=>s.id===sceneId)!.layers.find(l=>l.id===selectedLayer)!;target.swapAssetIds=[...new Set([...(target.swapAssetIds??[]),target.assetId!,asset.id])];target.assetId=asset.id;target.swapIndex=target.swapAssetIds.length-1;});tell('Artwork replaced; the rig and animation were preserved.');}catch(e){tell((e as Error).message);}finally{if(replaceInput.current)replaceInput.current.value='';}}
  async function importAudio(file:File|undefined){if(!file)return;setBusy('Reading audio…');try{if(!/\.(wav|mp3)$/i.test(file.name))throw new Error('Import a WAV or MP3 audio file.');audio.current??=new AudioEngine();const asset={id:id(),name:file.name,type:'audio' as const,mime:file.name.toLowerCase().endsWith('.wav')?'audio/wav':'audio/mpeg',width:0,height:0,data:await fileData(file)};const metadata=await audio.current.analyze(asset);commit('Import audio',p=>{p.assets.push({...asset,...metadata});p.sequence.audio.push({id:id(),assetId:asset.id,start:sequenceTime,sourceIn:0,duration:metadata.duration,volume:1,fadeIn:0,fadeOut:0,volumeKeys:[]});});changeWorkspace('assemble');tell('Audio added to the master sequence.');}catch(e){tell((e as Error).message);}finally{setBusy('');if(audioInput.current)audioInput.current.value='';}}
  function newScene(){const s=makeScene(`0${project.scenes.length+1} · New shot`);commit('Create shot',p=>{p.scenes.push(s);p.sequence.shots.push({id:id(),sceneId:s.id,start:Math.max(0,...p.sequence.shots.map(s=>s.start+s.duration)),duration:s.duration,sourceIn:0});});setSceneId(s.id);setTime(0);selectLayer('');setTab('shots');}
  function duplicateLayer(){if(!layer)return;const included=connectedPieceIds(scene,layer.id),mapping=new Map([...included].map(old=>[old,id()]));const copies=scene.layers.filter(l=>included.has(l.id)).map(l=>{const copy=snapshot(l);copy.id=mapping.get(l.id)!;copy.name=l.id===layer.id?`${l.name} copy`:l.name;if(copy.parentId)copy.parentId=mapping.get(copy.parentId)??copy.parentId;if(copy.attachment)copy.attachment.layerId=mapping.get(copy.attachment.layerId)??copy.attachment.layerId;if(l.id===layer.id)copy.rigPlacement=multiply([1,0,0,1,80,0],copy.rigPlacement??identity());return copy;});commit('Create connected character instance',p=>{const s=p.scenes.find(s=>s.id===sceneId)!;copyCharacterMetadata(s,scene,mapping);s.layers.unshift(...copies);s.tracks.push(...s.tracks.filter(t=>included.has(t.targetId)).map(t=>({...snapshot(t),id:id(),targetId:mapping.get(t.targetId)!,keys:t.keys.map(k=>({...snapshot(k),id:id()}))})));s.clips.push(...s.clips.filter(c=>included.has(c.targetId)).map(c=>({...snapshot(c),id:id(),targetId:mapping.get(c.targetId)!})));});selectLayer(mapping.get(layer.id)!);tell(`${copies.length} connected piece${copies.length===1?'':'s'} duplicated. Rigs are shared; animation is independent.`);}
