  async function addCharacter(sourceSceneId:string,rootId:string){const baseline=history.current.current,source=baseline.scenes.find(s=>s.id===sourceSceneId)!,include=connectedPieceIds(source,rootId);setBusy('Adding connected character…');try{const frame=await engine.current.evaluate(baseline,{...source,tracks:[],clips:[]},0);if(history.current.current!==baseline)throw new Error('The project changed. Please add the character again.');const mapping=new Map([...include].map(old=>[old,id()])),layers=source.layers.filter(l=>include.has(l.id)).map(l=>{const copy=snapshot(l);if(l.id===rootId&&(l.attachment&&!include.has(l.attachment.layerId)||l.parentId&&!include.has(l.parentId))){copy.attachment=undefined;copy.parentId=undefined;copy.rigPlacement=multiply(frame.worlds![l.id],inverseMatrix(layerMatrix(l.transform)));}copy.id=mapping.get(l.id)!;copy.parentId=copy.parentId&&mapping.get(copy.parentId);if(copy.attachment)copy.attachment.layerId=mapping.get(copy.attachment.layerId)!;if(l.id===rootId)copy.name=`${l.name} instance`;return copy;});commit('Add reusable connected character',p=>{const s=p.scenes.find(s=>s.id===sceneId)!;s.layers.unshift(...layers);copyCharacterMetadata(s,source,mapping);});selectLayer(mapping.get(rootId)!);tell('Connected character added. Shared rig edits update every instance.');}catch(e){tell((e as Error).message);}finally{setBusy('');}}
