  async function removeLayer(){if(!layer)return;const baseline=history.current.current,source=baseline.scenes.find(s=>s.id===sceneId)!,removed=new Set([selectedLayer]);let changed=true;while(changed){changed=false;for(const l of source.layers)if(l.parentId&&removed.has(l.parentId)&&!removed.has(l.id)){removed.add(l.id);changed=true;}}try{const followers=source.layers.filter(l=>!removed.has(l.id)&&l.attachment&&removed.has(l.attachment.layerId)),frame=followers.length?await engine.current.evaluate(baseline,workspace==='rig'?{...source,tracks:[],clips:[]}:source,time):undefined;if(history.current.current!==baseline)throw new Error('The project changed. Please remove the layer again.');commit('Remove layer',p=>{const s=p.scenes.find(s=>s.id===sceneId)!;if(frame){detachCharacterParts(p,s,followers.map(l=>l.id),frame);bindPieces(s,followers.map(l=>l.id),undefined,frame);}s.characters=s.characters.filter(c=>!removed.has(c.rootLayerId)).map(c=>({...c,parts:c.parts.filter(part=>!removed.has(part.layerId))}));s.layers=s.layers.filter(l=>!removed.has(l.id));s.tracks=s.tracks.filter(t=>!removed.has(t.targetId));s.clips=s.clips.filter(c=>!removed.has(c.targetId));});selectLayer('');}catch(e){tell((e as Error).message);}}
  async function removeControl(){if(rig?.controlOnly){tell('Shared skeleton bones are managed by the character assistant.');return;}if(!rig||(!selectedPin&&!selectedBone))return;const baseline=history.current.current,controlId=selectedPin||selectedBone;try{const frames=new Map<string,Awaited<ReturnType<Engine['evaluate']>>>();for(const s of baseline.scenes){const targets=new Set(s.layers.filter(l=>l.rigId===rig.id).map(l=>l.id));if(s.layers.some(l=>l.attachment&&targets.has(l.attachment.layerId)&&l.attachment.controlId===controlId))frames.set(s.id,await engine.current.evaluate(baseline,{...s,tracks:[],clips:[]},0));}if(history.current.current!==baseline)throw new Error('The project changed. Please remove the control again.');commit('Remove rig control',p=>{for(const s of p.scenes){const frame=frames.get(s.id);if(frame)for(const l of s.layers)if(l.attachment?.controlId===controlId&&s.layers.find(t=>t.id===l.attachment!.layerId)?.rigId===rig.id)bindPieces(s,[l.id],{layerId:l.attachment.layerId,kind:'layer'},frame);s.tracks=s.tracks.filter(t=>!t.property.includes(controlId));}for(const clip of p.clips)if(clip.sourceRigId===rig.id)clip.tracks=clip.tracks.filter(t=>!t.property.includes(controlId));const r=p.rigs.find(r=>r.id===rig.id)!;r.pins=r.pins.filter(v=>v.id!==selectedPin);r.bones=r.bones.filter(v=>v.id!==selectedBone).map(b=>b.parentId===selectedBone?{...b,parentId:undefined}:b);r.revision++;});setSelectedPin('');setSelectedBone('');}catch(e){tell((e as Error).message);}}
