  useEffect(()=>{function key(e:KeyboardEvent){if(wizard){if(e.key==='Escape')setWizard(false);return;}const input=e.target as HTMLElement;const inField=['INPUT','TEXTAREA','SELECT'].includes(input.tagName);if(inField&&(!(e.ctrlKey||e.metaKey)||['c','v','z'].includes(e.key.toLowerCase())))return;if(e.key==='Escape'){setWizard(false);if(pieceMode){setPieceMode(false);selectLayer(characterRoot(scene,selectedLayer));}setModal(null);setContextLayer('');setSelectedKeys([]);return;}if(e.ctrlKey||e.metaKey){const k=e.key.toLowerCase();if(['s','o','i','e','d','z','k','c','v'].includes(k))e.preventDefault();if(k==='s'){if(inField)input.blur();setTimeout(()=>void save(e.shiftKey),0);}if(k==='o')void open();if(k==='i')artworkInput.current?.click();if(k==='e')setModal('export');if(k==='d'){if(selectedKeys.length)pasteSelectedKeys(true);else duplicateLayer();}if(k==='z')e.shiftKey?redo():undo();if(k==='k')setModal('commands');if(k==='c'){if(e.shiftKey)copyPose();else copySelectedKeys();}if(k==='v'){if(e.shiftKey)pastePose();else pasteSelectedKeys();}return;}if(modal)return;if(e.code==='Space'){e.preventDefault();void togglePlay();}if(e.key==='ArrowLeft')seek(Math.max(0,(workspace==='assemble'?sequenceTime:time)-1/fps));if(e.key==='ArrowRight')seek((workspace==='assemble'?sequenceTime:time)+1/fps);if(e.key.toLowerCase()==='k')addSelectedKey();if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='g')setTool('translate');if(e.key.toLowerCase()==='p'){changeWorkspace('rig');setTool('move');}if(e.key.toLowerCase()==='b'){changeWorkspace('rig');setTool('bone');}if(e.key==='F2')renameLayer();if(e.key==='Delete'){if(selectedKeys.length)deleteKeys();else if(selectedPin||selectedBone)removeControl();else removeLayer();}}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);});
